import { AppState } from 'react-native';
import { INSIGHT_NOTIFICATION_EVENTS, INSIGHT_NOTIFICATION_OWNER, REMINDER_PERMISSION_STATES } from '@/constants';
import type { BeliefStatement } from '@/features/beliefs/domain/belief-statement';
import type { CheckIn } from '@/features/check-in/domain/check-in';
import type { AppLocale } from '@/localization/app-locale';
import type { ReminderLocalTime } from '@/features/reminders/domain/reminder-timing';
import { getReminderPermission, requestReminderPermission } from '@/features/reminders/infrastructure/local-reminder.scheduler';
import { loadInsightNotificationState, persistInsightNotificationState } from '../infrastructure/insight-notification.repository';
import { reconcileInsightBatch, cancelInsightNotifications } from '../infrastructure/insight-notification.scheduler';
import { insightCandidates, nextInsightDelivery, pendingInsightCandidates, type InsightNotificationState } from '../domain/insight-notification';
import { createInsightNotificationStore } from './insight-notification.store';

export type InsightNotificationCommand =
  | { type: typeof INSIGHT_NOTIFICATION_EVENTS.ENABLED }
  | { type: typeof INSIGHT_NOTIFICATION_EVENTS.DISABLED }
  | { type: typeof INSIGHT_NOTIFICATION_EVENTS.DISMISSED }
  | { type: typeof INSIGHT_NOTIFICATION_EVENTS.RECHECK_REQUESTED }
  | { type: typeof INSIGHT_NOTIFICATION_EVENTS.SYSTEM_SETTINGS_REQUESTED }
  | { type: typeof INSIGHT_NOTIFICATION_EVENTS.TIME_CHANGED; time: ReminderLocalTime }
  | { type: typeof INSIGHT_NOTIFICATION_EVENTS.PICKER_CHANGED; open: boolean };
export interface InsightData {
  entries: readonly CheckIn[]; statements: readonly BeliefStatement[]; locale: AppLocale; ready: boolean;
}
export interface InsightDependencies {
  load: typeof loadInsightNotificationState; persist: typeof persistInsightNotificationState;
  permission: typeof getReminderPermission; requestPermission: typeof requestReminderPermission;
  reconcile: typeof reconcileInsightBatch; cancel: typeof cancelInsightNotifications;
  now: () => Date; nonce: () => string; openSettings: () => Promise<void>;
}

export class InsightNotificationCoordinator {
  private queue: Promise<void> = Promise.resolve();
  private loaded = false;
  private resetting = false;
  private data: InsightData | null = null;
  private active = true;
  private readonly store: ReturnType<typeof createInsightNotificationStore>;
  private readonly deps: InsightDependencies;
  constructor({ store, deps }: { store: ReturnType<typeof createInsightNotificationStore>; deps: InsightDependencies }) {
    this.store = store; this.deps = deps;
  }

  private enqueue(task: () => Promise<void>) {
    const run = async () => {
      this.store.trigger.busyChanged({ busy: true });
      try { await task(); }
      catch { this.store.trigger.failed({ message: 'Insight notifications could not be updated. Try again.' }); }
      finally { this.store.trigger.busyChanged({ busy: false }); }
    };
    this.queue = this.queue.then(run);
    return this.queue;
  }
  private async load() {
    if (this.loaded) return;
    const state = await this.deps.load();
    this.store.trigger.updated({ settings: state });
    this.loaded = true;
  }
  private async save(settings: InsightNotificationState) {
    await this.deps.persist(settings);
    this.store.trigger.updated({ settings });
  }
  update(data: InsightData) {
    this.data = data;
    if (!data.ready || !this.active) return this.queue;
    return this.enqueue(async () => { await this.load(); await this.evaluate(); });
  }
  setActive(active: boolean) {
    this.active = active;
    if (active && this.data) return this.update(this.data);
    return this.queue;
  }
  reset() {
    this.resetting = true;
    return this.enqueue(async () => {
      await this.deps.cancel();
      await this.load();
      const state = this.store.getSnapshot().context.settings;
      await this.save({ ...state, pending: null });
    });
  }
  private candidates() {
    if (!this.data?.ready) return [];
    return insightCandidates({ entries: this.data.entries, statements: this.data.statements, now: this.deps.now() });
  }
  private async evaluate() {
    if (!this.data?.ready || !this.active) return;
    let state = this.store.getSnapshot().context.settings;
    const candidates = this.candidates();
    if (this.resetting) {
      await this.deps.cancel();
      await this.save({ ...state, seen: candidates.map(({ id }) => id), pending: null });
      this.resetting = false;
      return;
    }
    const permission = await this.deps.permission();
    this.store.trigger.permissionChanged({ permission });
    if (!state.enabled || permission !== REMINDER_PERMISSION_STATES.GRANTED) {
      await this.deps.cancel();
      return;
    }
    if (state.pending && new Date(state.pending.fireAt) <= this.deps.now()) {
      state = { ...state, seen: [...new Set([...state.seen, ...state.pending.candidates.map(({ id }) => id)])], pending: null };
    }
    await this.scheduleCandidates({ state, candidates });
  }
  private async scheduleCandidates({ state, candidates }: {
    state: InsightNotificationState; candidates: ReturnType<typeof insightCandidates>;
  }) {
    if (!this.data) return;
    const pending = pendingInsightCandidates({ state, candidates });
    const [first, ...rest] = pending;
    const batch = first ? {
      id: state.pending?.id ?? `${INSIGHT_NOTIFICATION_OWNER}-${this.deps.now().getTime()}-${this.deps.nonce()}`,
      fireAt: state.pending?.fireAt ?? nextInsightDelivery({ now: this.deps.now(), time: state.time }).toISOString(),
      candidates: [first, ...rest] satisfies readonly [typeof first, ...typeof rest],
    } : null;
    await this.save({ ...state, pending: batch });
    await this.deps.reconcile({ batch, locale: this.data.locale });
  }
  command(event: InsightNotificationCommand) {
    if (event.type === INSIGHT_NOTIFICATION_EVENTS.PICKER_CHANGED) {
      this.store.trigger.pickerChanged({ open: event.open });
      return this.queue;
    }
    return this.enqueue(async () => { await this.load(); await this.applyCommand(event); });
  }
  private async applyCommand(event: InsightNotificationCommand) {
    const state = this.store.getSnapshot().context.settings;
    if (event.type === INSIGHT_NOTIFICATION_EVENTS.SYSTEM_SETTINGS_REQUESTED) return this.deps.openSettings();
    if (event.type === INSIGHT_NOTIFICATION_EVENTS.RECHECK_REQUESTED) return this.evaluate();
    if (event.type === INSIGHT_NOTIFICATION_EVENTS.DISMISSED) return this.save({ ...state, dismissed: true });
    if (event.type === INSIGHT_NOTIFICATION_EVENTS.DISABLED) {
      await this.deps.cancel();
      return this.save({ ...state, enabled: false, pending: null });
    }
    if (event.type === INSIGHT_NOTIFICATION_EVENTS.TIME_CHANGED) {
      await this.save({ ...state, time: event.time, pending: state.pending
        ? { ...state.pending, fireAt: nextInsightDelivery({ now: this.deps.now(), time: event.time }).toISOString() } : null });
      return this.evaluate();
    }
    if (event.type !== INSIGHT_NOTIFICATION_EVENTS.ENABLED || state.enabled || !this.data?.ready || !this.active) return;
    const permission = await this.deps.requestPermission();
    this.store.trigger.permissionChanged({ permission });
    if (permission !== REMINDER_PERMISSION_STATES.GRANTED) return;
    await this.save({ ...state, enabled: true, dismissed: true, seen: this.candidates().map(({ id }) => id), pending: null });
    await this.evaluate();
  }
}

export function watchInsightAppState(coordinator: InsightNotificationCoordinator) {
  void coordinator.setActive(AppState.currentState === 'active');
  return AppState.addEventListener('change', (state) => { void coordinator.setActive(state === 'active'); });
}
import type { InsightCandidate } from '../domain/insight-notification';
import { InsightNotificationCoordinator, watchInsightAppState, type InsightDependencies, type InsightData, type InsightNotificationCommand } from './insight-notification-coordinator';
import type { createInsightNotificationStore } from './insight-notification.store';

export interface InsightRuntimeBinding {
  data: () => InsightData;
  subscribe: (notify: () => void) => { unsubscribe: () => void };
  onStop: (stop: () => void) => void;
}
export interface InsightNotificationRuntime {
  start: (binding: InsightRuntimeBinding) => void;
  command: (event: InsightNotificationCommand) => void;
  reset: () => void;
}
export function createInsightNotificationRuntime({ store, deps }: { store: ReturnType<typeof createInsightNotificationStore>; deps: InsightDependencies }): InsightNotificationRuntime {
  const coordinator = new InsightNotificationCoordinator({ store, deps });
  return {
    start(binding) {
      let previous: InsightData | undefined;
      const notify = () => {
        const data = binding.data();
        if (previous?.entries === data.entries && previous.statements === data.statements
          && previous.locale === data.locale && previous.ready === data.ready) return;
        previous = data;
        void coordinator.update(data);
      };
      const subscription = binding.subscribe(notify);
      const appState = watchInsightAppState(coordinator);
      binding.onStop(() => { subscription.unsubscribe(); appState.remove(); void coordinator.setActive(false); });
      notify();
    },
    command: (event) => { void coordinator.command(event); },
    reset: () => { void coordinator.reset(); },
  };
}
export type InsightOpenedEvent = { type: 'insightNotificationOpened'; target: InsightCandidate };
import { createStore } from '@xstate/store';
import * as Schema from 'effect/Schema';
import { REMINDER_PERMISSION_STATES } from '@/constants';
import { initialInsightNotificationState, InsightNotificationStateSchema } from '../domain/insight-notification';

const PermissionSchema = Schema.Literal(...Object.values(REMINDER_PERMISSION_STATES));
export function createInsightNotificationStore() {
  return createStore({
    schemas: {
      context: Schema.standardSchemaV1(Schema.Struct({
        settings: InsightNotificationStateSchema, hydrated: Schema.Boolean, busy: Schema.Boolean,
        pickerOpen: Schema.Boolean, permission: PermissionSchema, error: Schema.NullOr(Schema.String),
      })),
      events: {
        updated: Schema.standardSchemaV1(Schema.Struct({ settings: InsightNotificationStateSchema })),
        busyChanged: Schema.standardSchemaV1(Schema.Struct({ busy: Schema.Boolean })),
        permissionChanged: Schema.standardSchemaV1(Schema.Struct({ permission: PermissionSchema })),
        pickerChanged: Schema.standardSchemaV1(Schema.Struct({ open: Schema.Boolean })),
        failed: Schema.standardSchemaV1(Schema.Struct({ message: Schema.String })),
      },
    },
    context: { settings: initialInsightNotificationState(), hydrated: false, busy: false,
      pickerOpen: false, permission: REMINDER_PERMISSION_STATES.UNDETERMINED, error: null },
    on: {
      updated: (context, event) => ({ ...context, settings: event.settings, hydrated: true, error: null }),
      busyChanged: (context, event) => ({ ...context, busy: event.busy }),
      permissionChanged: (context, event) => ({ ...context, permission: event.permission }),
      pickerChanged: (context, event) => ({ ...context, pickerOpen: event.open }),
      failed: (context, event) => ({ ...context, error: event.message }),
    },
  });
}

